return [sorted[0]];

const raw = ($input.first().json.data || '').toString();
const texto = raw.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
if (!texto || texto.length < 100) {
  throw new Error('Texto extraido vazio ou curto demais (' + texto.length + ' caracteres). Verifique o PPTX de entrada.');
}
const nomeOriginal = $('Pegar Mais Antigo').first().json.name || 'aula';
return [{ json: {
  source_text: texto,
  char_count: texto.length,
  nome_base: nomeOriginal.replace(/\.[^.]+$/, '')
} }];

const src = $('Normalizar Texto').first().json;
const system = 'Você é um revisor especialista em legislação para concursos públicos. Você recebe o texto extraído dos slides de uma aula e verifica se cada norma citada (lei, decreto, artigo, parágrafo, inciso, súmula, jurisprudência) está vigente e com a redação atual.' +
' REGRAS DE VERIFICAÇÃO: 1. Use a ferramenta web_search para checar CADA dispositivo citado, priorizando fontes oficiais: planalto.gov.br, in.gov.br (Diário Oficial), stf.jus.br, stj.jus.br e sites de tribunais.' +
' 2. Só aponte divergência quando encontrar fonte que a comprove. NUNCA corrija de memória. Se não conseguir confirmar um dispositivo, registre na lista de divergências com situacao igual a nao_verificado e gravidade baixa.' +
' 3. Não invente dispositivo legal e não cite lei que não encontrou na busca.' +
' PROIBIDO: travessão em qualquer texto (use dois pontos, vírgula ou ponto). OBRIGATÓRIO: acentuação portuguesa perfeita.' +
' FORMATO DE SAÍDA: retorne APENAS um objeto JSON válido, sem markdown, sem crases e sem texto fora do JSON. Schema exato: {"titulo": string, "status": "atualizado" | "com_divergencias", "divergencias": [{"topico": string, "trecho_slide": string, "situacao": string, "texto_atual": string, "fonte": string, "gravidade": "alta" | "media" | "baixa"}], "conteudo_atualizado": string}.' +
' O campo conteudo_atualizado deve conter o conteúdo INTEGRAL da aula, tópico por tópico, na mesma ordem do original, já com as correções aplicadas, sem cortar nenhum assunto e sem resumir. Se nada mudou, status é atualizado, divergencias é lista vazia e conteudo_atualizado reproduz o conteúdo original organizado por tópicos.';
const body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 30000,
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 10 }],
  system: system,
  messages: [{ role: 'user', content: 'Verifique a atualidade da legislação e devolva o JSON conforme o schema do sistema.\n\nConteúdo extraído dos slides:\n\n' + src.source_text }]
};
return [{ json: { anthropic_body: body, nome_base: src.nome_base } }];

const resp = $input.first().json || {};
const blocks = Array.isArray(resp.content) ? resp.content : [];
let texto = blocks.filter(b => b.type === 'text').map(b => b.text || '').join('\n');
if (!texto) throw new Error('Resposta vazia do Claude. Keys: ' + Object.keys(resp).join(', '));
if (resp.stop_reason === 'max_tokens') throw new Error('Resposta do Claude truncada no limite de tokens. Aumente max_tokens no prompt de verificacao ou divida a aula.');
texto = texto.replace(/```json|```/g, '').trim();
const ini = texto.indexOf('{');
const fim = texto.lastIndexOf('}');
if (ini < 0 || fim <= ini) throw new Error('JSON nao encontrado. Inicio da resposta: ' + texto.substring(0, 300));
let out;
try { out = JSON.parse(texto.substring(ini, fim + 1)); }
catch (e) { throw new Error('JSON invalido: ' + e.message + '. Trecho: ' + texto.substring(0, 300)); }
function limpa(v) {
  if (typeof v === 'string') return v.replace(/\s*[\u2014\u2013]\s*/g, ', ');
  if (Array.isArray(v)) return v.map(limpa);
  if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = limpa(v[k]); return o; }
  return v;
}
out = limpa(out);
if (!out.conteudo_atualizado) throw new Error('Campo conteudo_atualizado ausente na resposta');
const divs = Array.isArray(out.divergencias) ? out.divergencias : [];
const nome = $('Normalizar Texto').first().json.nome_base || 'aula';
const arquivoOriginal = $('Pegar Mais Antigo').first().json.name || '';
let md = '# Relatorio de Atualizacao: ' + (out.titulo || nome) + '\n\n';
md += 'Arquivo original: ' + arquivoOriginal + '\n';
md += 'Data da verificacao: ' + new Date().toISOString() + '\n';
md += 'Status: ' + (out.status || 'desconhecido') + '\n';
md += 'Divergencias encontradas: ' + divs.length + '\n\n';
if (divs.length === 0) {
  md += 'Nenhuma divergencia com fonte foi encontrada. Confira por amostragem antes de publicar.\n';
}
for (const d of divs) {
  md += '## [' + (d.gravidade || 'sem gravidade') + '] ' + (d.topico || '') + '\n\n';
  md += 'Trecho no slide: ' + (d.trecho_slide || '') + '\n\n';
  md += 'Situacao: ' + (d.situacao || '') + '\n\n';
  md += 'Texto atual: ' + (d.texto_atual || '') + '\n\n';
  md += 'Fonte: ' + (d.fonte || '') + '\n\n';
}
md += '\nAVISO: revisao humana obrigatoria. Confirme cada ponto de gravidade alta no site do Planalto antes de usar o material com alunos.\n';
return [{ json: {
  conteudo_atualizado: out.conteudo_atualizado,
  titulo: out.titulo || nome,
  status: out.status || 'desconhecido',
  divergencias: divs,
  relatorio_md: md,
  nome_base: nome
} }];

const src = $input.first().json;
const system = 'Você é um professor especialista em concursos públicos que transforma o conteúdo atualizado de uma aula em ROTEIRO DE SLIDES COMPLETO para o próprio professor apresentar em sala.' +
' PREMISSA: o deck cobre TODO o conteúdo recebido, do início ao fim, na mesma ordem e no mesmo nível de detalhe. Nada é cortado, nada é resumido, nada é agrupado por economia de espaço. A densidade vem da QUANTIDADE de slides, não do tamanho de cada slide: slide curto e legível, deck longo.' +
' PROIBIDO: parágrafos longos dentro do slide, oralidade, rodeios, travessão (use dois pontos, vírgula ou ponto), resumir para caber, pular assunto secundário, juntar dois subtópicos no mesmo slide.' +
' OBRIGATÓRIO: acentuação portuguesa perfeita.' +
' FORMATO DE SAÍDA: retorne APENAS um objeto JSON válido, sem markdown, sem crases, sem texto antes ou depois. Schema exato: {"titulo_aula": string, "subtitulo": string, "slides": [array de objetos]}.' +
' Tipos de slide permitidos no array: {"tipo":"agenda","titulo":"Roteiro da aula","itens":[um item por tópico, na ordem]} (sempre o primeiro slide); {"tipo":"secao","numero":N,"titulo":string} para abrir cada bloco temático; {"tipo":"conteudo","titulo":string,"bullets":[3 a 6 strings],"notas":string}; {"tipo":"definicao","termo":string,"texto":string} para conceitos centrais e dispositivos legais; {"tipo":"caixa","estilo":"atencao"|"dica"|"pegadinha","titulo":string,"texto":string}.' +
' REGRAS DE COBERTURA: 1. Não existe teto de slides; gere quantos forem necessários. 2. Cada tópico abre com um slide secao; cada subtópico recebe no mínimo dois slides de conteudo; cada conceito nuclear recebe um slide definicao; cada erro induzido pela banca recebe uma caixa pegadinha; cada ponto crítico recebe uma caixa atencao; cada macete recebe uma caixa dica. 3. Um slide de conteudo trata de UM assunto só; se render mais de 6 bullets, fatie em slides sequenciais com sufixo (2), (3). 4. Toda enumeração (requisitos, espécies, hipóteses, prazos, exceções, competências, vedações) vira slide próprio, com um item por bullet, na íntegra. 5. Todo dispositivo legal citado no conteúdo entra em slide definicao com a referência exata.';
const body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 32000,
  system: system,
  messages: [{ role: 'user', content: 'Transforme o conteúdo abaixo no roteiro de slides JSON, seguindo rigorosamente o schema do sistema.\n\nConteúdo atualizado da aula:\n\n' + (src.conteudo_atualizado || '') }]
};
return [{ json: { anthropic_body: body, nome_base: src.nome_base } }];

const resp = $input.first().json || {};
const blocks = Array.isArray(resp.content) ? resp.content : [];
let texto = blocks.filter(b => b.type === 'text').map(b => b.text || '').join('\n');
if (!texto) throw new Error('Resposta vazia do Claude. Keys: ' + Object.keys(resp).join(', '));
if (resp.stop_reason === 'max_tokens') {
  throw new Error('Resposta do Claude truncada no limite de tokens. Aumente max_tokens no no Montar Prompt Slides ou divida a aula em duas partes.');
}
texto = texto.replace(/```json|```/g, '').trim();
const ini = texto.indexOf('{');
const fim = texto.lastIndexOf('}');
if (ini < 0 || fim <= ini) throw new Error('JSON nao encontrado. Inicio da resposta: ' + texto.substring(0, 300));
let deck;
try { deck = JSON.parse(texto.substring(ini, fim + 1)); }
catch (e) { throw new Error('JSON invalido: ' + e.message + '. Trecho: ' + texto.substring(0, 300)); }
if (!deck.titulo_aula) deck.titulo_aula = $('Validar Verificacao').first().json.titulo || 'Aula';
if (!Array.isArray(deck.slides) || deck.slides.length === 0) throw new Error('Campo slides ausente ou vazio');
function limpa(v) {
  if (typeof v === 'string') return v.replace(/\s*[\u2014\u2013]\s*/g, ', ');
  if (Array.isArray(v)) return v.map(limpa);
  if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = limpa(v[k]); return o; }
  return v;
}
deck = limpa(deck);
return [{ json: { deck: deck, total_slides: deck.slides.length } }];

const item = $input.first();
if (!item.binary || !item.binary.data) {
  const keys = item.binary ? Object.keys(item.binary).join(', ') : '(sem binary)';
  throw new Error('PPTX ausente na resposta do servico. Binary keys: ' + keys);
}
const nome = $('Normalizar Texto').first().json.nome_base || 'aula';
const fileName = nome + '_Atualizado.pptx';
// Preserva a referencia original do binario (modo filesystem): nao reconstroi o campo data
const novoBinario = Object.assign({}, item.binary.data, {
  fileName: fileName,
  mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
});
return [{
  json: { pptx_ready: true, pptx_filename: fileName },
  binary: { data: novoBinario }
}];
